$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const btn=e.submitter||e.target.querySelector('button[type=submit],button');btn.disabled=true;btn.textContent='جارٍ تسجيل الدخول...';$('#loginError').textContent='';try{me=await api('/login',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});$('#login').hidden=true;$('#app').hidden=false;await boot()}catch(err){$('#loginError').textContent=err.message||'تعذر تسجيل الدخول';if(me){$('#login').hidden=true;$('#app').hidden=false;$('#page').innerHTML=`<div class="panel error">تم تسجيل الدخول لكن تعذر تحميل لوحة التحكم: ${esc(err.message)}. حدّث الصفحة أو راجع نافذة السيرفر.</div>`}}finally{btn.disabled=false;btn.textContent='تسجيل الدخول'}});
async function getFollowupReminderNotifications(){if(!allowed('followups')||!(me?.role==='admin'||me?.permissions?.includes('notify_followups')))return [];try{const data=await api('/followups'),rows=asRows(data.followups),now=new Date(),today=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`;return rows.filter(f=>{const d=new Date(f.scheduled_at);if(Number.isNaN(d.getTime()))return false;const day=`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;return day<=today}).map(f=>({id:-Number(f.id),reminder:true,action:'followup_reminder',title:new Date(f.scheduled_at)<now?'متابعة عميل متأخرة':'موعد متابعة عميل اليوم',details:`العميل: ${f.customer_name||'—'} · الموبايل: ${f.phone||'—'} · موعد المتابعة: ${new Date(f.scheduled_at).toLocaleString('ar-EG',{dateStyle:'medium',timeStyle:'short'})} · الحالة: ${f.inquiry_status||'يحتاج متابعة'}`,employee:f.employee||'خدمة العملاء',created_at:f.scheduled_at,inquiry_id:f.inquiry_id,scheduled_at:f.scheduled_at})).sort((a,b)=>new Date(a.scheduled_at)-new Date(b.scheduled_at))}catch{return []}}
async function refreshBell(){try{const base=asRows(await api('/notifications')),reminders=await getFollowupReminderNotifications(),rows=[...reminders,...base];const menu=$('#bellItems'),count=$('#bellCount');if(!menu)return;const key='nasim_seen_notifications_'+(me?.id||me?.username||'user');let seen=[];try{seen=JSON.parse(localStorage.getItem(key)||'[]')}catch{}const unread=rows.filter(n=>!seen.includes(Number(n.id)));count.textContent=unread.length;count.hidden=!unread.length;menu.innerHTML=rows.length?rows.slice(0,8).map(n=>`<button type="button" class="bell-item ${n.reminder?'bell-reminder-item':''}" onclick="${n.reminder?'show(\'followups\')':'openNotificationPage()'}"><b>${n.reminder?'🔔 ':''}${esc(n.title||'عملية بالنظام')}</b><span>${esc(n.details||'تم تسجيل عملية بالنظام')}</span><small>${esc(n.employee||'النظام')} · ${esc(new Date(n.created_at).toLocaleString('ar-EG'))}</small></button>`).join(''):'<p class="muted bell-empty">لا توجد تنبيهات مسجلة.</p>'}catch{}}
