 $('#exportTrialBalance').onclick=()=>{const r=window._nasimAccountingReports;if(!r){notice('اعرض التقارير أولًا',true);return}downloadExcel('ميزان-المراجعة-'+r.from+'-'+r.to+'.xls','ميزان المراجعة '+r.from+' إلى '+r.to,['كود الحساب','الحساب','النوع','افتتاحي مدين','افتتاحي دائن','حركة مدين','حركة دائن','ختامي مدين','ختامي دائن'],r.tb.map(x=>[x.code,x.name,({asset:'أصول',liability:'التزامات',equity:'حقوق ملكية',revenue:'إيرادات',expense:'مصروفات'})[x.account_type]||x.account_type,x.opening_debit,x.opening_credit,x.debit,x.credit,x.closing_debit,x.closing_credit]))};
