function filterOfferPackages(){const selected=allHallsCheckbox.checked?[]:hallChoiceCheckboxes.filter(c=>c.checked).map(c=>String(c.value));const hall=selected.length===1?selected[0]:'';for(const opt of packageSelect.options){if(!opt.value){opt.hidden=false;continue}opt.hidden=!!hall&&String(opt.dataset.hallId)!==hall;if(opt.hidden&&opt.selected)packageSelect.value=''} }
