async function requestBookingChange(id,defaultType){
 let booking;try{booking=await api(`/bookings/${id}/details`)}catch(e){notice(e.message,true);return}
 if(defaultType==='items'){window.editBooking(id);return}
 const safe=x=>String(x??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
 const overlay=document.createElement('div');overlay.className='collection-modal';overlay.innerHTML=`<div class="collection-dialog action-dialog" role="dialog" aria-modal="true" aria-labelledby="bookingChangeTitle"><div class="page-head"><div><h2 id="bookingChangeTitle">طلب تعديل الحجز ${safe(booking.booking_no)}</h2><p class="muted">${safe(booking.customer_name)} · ${safe(booking.hall_name)} · ${safe(booking.event_date)} · ${safe(booking.start_time)}–${safe(booking.end_time)}</p></div><button type="button" class="secondary" id="closeBookingChange">إغلاق</button></div><div class="cards" style="margin-bottom:16px"><button type="button" class="secondary" data-change-kind="change_date">تغيير الموعد</button><button type="button" class="danger" data-change-kind="cancel">إلغاء الحجز</button></div><form id="bookingChangeForm" class="grid-form"><input type="hidden" name="change_type" value="${defaultType==='change_date'?'change_date':defaultType==='cancel'?'cancel':'items'}"><div class="full" id="changeKindHint" style="padding:12px;border-radius:10px;background:#eaf0f8;color:#173c5b;font-weight:800">اختر نوع الطلب من الأزرار أعلاه.</div><div class="full" id="changeFields"></div><label class="full">سبب الطلب <textarea name="reason" required minlength="3" placeholder="اكتب سبب طلب العميل بالتفصيل"></textarea></label><div class="full inline"><button type="submit" id="submitBookingChange">إرسال الطلب للمدير</button><button type="button" class="secondary" id="cancelBookingChange">إلغاء</button></div></form></div>`;
 document.body.appendChild(overlay);const form=overlay.querySelector('#bookingChangeForm'),fields=overlay.querySelector('#changeFields'),hint=overlay.querySelector('#changeKindHint'),kindInput=form.elements.change_type;let kind='';
 const setKind=k=>{kind=k;kindInput.value=k;overlay.querySelectorAll('[data-change-kind]').forEach(b=>{b.className=b.dataset.changeKind===k?(k==='cancel'?'danger':''):'secondary'});if(k==='change_date'){hint.textContent='حدد الموعد الجديد. سيتم التحقق من توافر القاعة عند اعتماد المدير.';fields.innerHTML=`<div class="grid-form"><label>التاريخ الجديد<input type="date" name="new_event_date" min="${new Date().toISOString().slice(0,10)}" required></label><label>وقت البداية الجديد<input type="time" lang="en-US" name="new_start_time" value="${safe(booking.start_time||'18:00')}" required></label><label>وقت النهاية الجديد<input type="time" lang="en-US" name="new_end_time" value="${safe(booking.end_time||'23:00')}" required></label></div>`}else if(k==='cancel'){hint.textContent='سيبقى الحجز كما هو حتى يراجع المدير الطلب ويوافق عليه.';fields.innerHTML='<p class="muted">سيظهر للمدير تفاصيل الحجز والمبالغ المسددة ليحدد الخصم غير المسترد أو المبلغ المستحق.</p>'}else{hint.textContent='حدد هل تريد إضافة صنف أو إلغاء صنف، واكتب اسم الصنف وتفاصيله.';fields.innerHTML='<div class="grid-form"><label>نوع العملية<select name="item_action" required><option value="add">إضافة صنف</option><option value="remove">إلغاء صنف</option></select></label><label>اسم الصنف والتفاصيل<input name="item_details" required placeholder="اسم الصنف والكمية والتفاصيل"></label></div>'}};
 overlay.querySelectorAll('[data-change-kind]').forEach(b=>b.onclick=()=>{if(b.dataset.changeKind==='items'){overlay.remove();window.editBooking(id);return}setKind(b.dataset.changeKind)});overlay.querySelector('#closeBookingChange').onclick=()=>overlay.remove();overlay.querySelector('#cancelBookingChange').onclick=()=>overlay.remove();overlay.addEventListener('click',e=>{if(e.target===overlay)overlay.remove()});form.onsubmit=async e=>{e.preventDefault();if(!kind){notice('اختار نوع الطلب أولًا',true);return}const fd=new FormData(form),d={change_type:kind,reason:String(fd.get('reason')||'').trim()};if(d.reason.length<3){notice('اكتب سبب الطلب بالتفصيل',true);return}if(kind==='change_date'){d.new_event_date=fd.get('new_event_date');d.new_start_time=fd.get('new_start_time');d.new_end_time=fd.get('new_end_time');if(!d.new_event_date||!d.new_start_time||!d.new_end_time){notice('أكمل التاريخ ووقت البداية والنهاية',true);return}if(d.new_end_time<=d.new_start_time){notice('وقت النهاية لازم يكون بعد وقت البداية',true);return}}else if(kind==='items'){d.item_action=fd.get('item_action');d.item_details=String(fd.get('item_details')||'').trim();if(!d.item_details){notice('اكتب تفاصيل الصنف',true);return}}
 const submit=form.querySelector('[type=submit]');submit.disabled=true;submit.textContent='جارٍ إرسال الطلب…';try{const r=await api('/bookings/'+id+'/change-requests',{method:'POST',body:JSON.stringify(d)});overlay.remove();notice(r.message||'تم إرسال الطلب للمدير للمراجعة')}catch(err){notice(err.message,true);submit.disabled=false;submit.textContent='إرسال الطلب للمدير'}};
 if(defaultType==='items'){overlay.remove();window.editBooking(id);return}if(defaultType==='change_date'||defaultType==='cancel')setKind(defaultType);else hint.textContent='اختر نوع الطلب من الأزرار أعلاه.';
}
